package example.orders;

import java.time.Clock;
import java.time.Instant;
import java.util.Objects;
import org.springframework.stereotype.Service;

@Service
public final class ReservationService {
  private final Inventory inventory;
  private final Clock clock;

  public ReservationService(Inventory inventory, Clock clock) {
    this.inventory = Objects.requireNonNull(inventory);
    this.clock = Objects.requireNonNull(clock);
  }

  public Reservation reserve(String sku, int quantity, Instant expiresAt) {
    if (sku == null || sku.isBlank() || quantity < 1 || quantity > 50 || expiresAt == null) {
      throw new IllegalArgumentException("Invalid reservation");
    }
    Instant now = clock.instant();
    if (!expiresAt.isAfter(now)) throw new IllegalArgumentException("Expiry must be future");
    String normalized = sku.trim();
    if (inventory.available(normalized) < quantity) throw new IllegalStateException("Insufficient stock");
    Reservation reservation = new Reservation(normalized, quantity, now, expiresAt);
    inventory.reserve(reservation);
    return reservation;
  }
}

