import { useEffect, useRef, useState, type FormEvent } from "react";
import { Button, TextField } from "@mui/material";

export interface QuoteLookupProps {
  readonly lookup: (query: string, signal: AbortSignal) => Promise<string>;
}

export function QuoteLookup({ lookup }: QuoteLookupProps) {
  const [query, setQuery] = useState("");
  const [result, setResult] = useState("");
  const [error, setError] = useState("");
  const [pending, setPending] = useState(false);
  const sequence = useRef(0);
  const active = useRef<AbortController | null>(null);
  useEffect(() => () => {
    sequence.current += 1;
    active.current?.abort();
  }, []);

  async function submit(event: FormEvent<HTMLFormElement>): Promise<void> {
    event.preventDefault();
    const value = query.trim();
    if (value.length === 0) return;
    active.current?.abort();
    const controller = new AbortController();
    active.current = controller;
    const request = ++sequence.current;
    setResult("");
    setError("");
    setPending(true);
    try {
      const quote = await lookup(value, controller.signal);
      if (request === sequence.current) setResult(quote);
    } catch {
      if (request === sequence.current) setError("Lookup failed");
    } finally {
      if (request === sequence.current) setPending(false);
    }
  }

  return (
    <form aria-label="Quote lookup" onSubmit={(event) => { void submit(event); }}>
      <TextField label="Search query" value={query} onChange={(event) => setQuery(event.target.value)} />
      <Button type="submit" disabled={query.trim().length === 0}>Find quote</Button>
      {pending && <span role="status">Searching</span>}
      {result !== "" && <output aria-label="Quote">{result}</output>}
      {error !== "" && <p role="alert">{error}</p>}
    </form>
  );
}
